<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\UserProfileGenderVO;

trait UserProfileGenderAttributeHolder
{
    protected UserProfileGenderVO|string|null $gender = null;
    protected bool $genderAssigned = false;

    public function getGenderOrCurrent(?UserProfileGenderVO $gender): ?UserProfileGenderVO
    {
        return $this->genderAssigned ? ($this->gender === null ? null : UserProfileGenderVO::from($this->gender)) : $gender;
    }
    public function genderTryBuildInitial(ConstraintFailList $error): ?UserProfileGenderVO
    {
        return  UserProfileGenderVO::tryFrom($this->genderAssigned ? $this->gender : null, $error);
    }
    public function gender(UserProfileGenderVO|string|null $gender): static
    {
        $this->gender = $gender;
        $this->genderAssigned = true;
        return $this;
    }
    public function getGender(): ?string
    {
        return $this->gender instanceof UserProfileGenderVO ? $this->gender->value() : $this->gender;
    }
    public function isGenderAssigned(): bool
    {
        return $this->genderAssigned;
    }
    public function writeGenderTo(mixed $att): void
    {
        if ($this->genderAssigned) {
            $att->gender($this->gender);
        }
    }
    public function readGenderFrom(mixed $att): void
    {
        if ($att->isGenderAssigned()) {
            $gender = $att->getGender();
            $this->gender($gender);
        }
    }
    public function unsetGender(): static
    {
        $this->genderAssigned = false;
        return $this;
    }
    protected function withDefaultGender(): void
    {
    }
    protected function withAssertedGenderRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->genderAssigned = $this->genderAssigned) {
            $value->gender = UserProfileGenderVO::tryFrom($this->gender, $errorsList);
        }
    }
}
